<script lang="ts">
  import {onMount,untrack} from 'svelte';
  import {validateSoles,measureSoles,type SoleBinding,type SoleReview,type SolePoint} from './soles.ts';
  import type {Img} from '../../lib/image/png.ts';
  import type {Foot} from '../../lib/rig/motion.ts';
  let {binding,images,index,pause}:{binding:SoleBinding;images:Img[];index:number;pause:()=>void}=$props();
  const fixed=untrack(()=>binding),storage='pixeldoll.motionSoles.'+fixed.jobId;
  let doc=$state<SoleReview>({version:1,kind:'pixeldoll-rendered-sole-review',binding:fixed,frames:fixed.hashes.map(()=>({})),notes:''}),foot=$state<Foot>('RIGHT LEG'),landmark=$state<SolePoint['landmark']>('heel'),canvas=$state<HTMLCanvasElement>(),error=$state(''),status=$state('');
  const measured=$derived(measureSoles(doc));
  $effect(()=>{if(!canvas||!images[index])return;const image=images[index],ctx=canvas.getContext('2d')!;canvas.width=image.w;canvas.height=image.h;ctx.putImageData(new ImageData(new Uint8ClampedArray(image.data),image.w,image.h),0,0);for(const[f,p]of Object.entries(doc.frames[index])){ctx.fillStyle=f==='RIGHT LEG'?'#ff6565':'#657eff';ctx.fillRect(p.x-1,p.y,3,1);ctx.fillRect(p.x,p.y-1,1,3);}});
  function validated(value:unknown){const review=validateSoles(value,fixed);for(let i=0;i<review.frames.length;i++)for(const p of Object.values(review.frames[i]))if(!images[i].data[(Math.floor(p.y)*images[i].w+Math.floor(p.x))*4+3])throw new Error('A sole mark is on a transparent pixel. Pick a visible heel or toe.');return review;}
  function mark(event:PointerEvent){if(!canvas)return;pause();const r=canvas.getBoundingClientRect(),x=Math.floor((event.clientX-r.left)*canvas.width/r.width)+0.5,y=Math.floor((event.clientY-r.top)*canvas.height/r.height)+0.5;if(x>=0&&y>=0&&x<canvas.width&&y<canvas.height){if(!images[index].data[(Math.floor(y)*canvas.width+Math.floor(x))*4+3]){error='Pick a visible heel or toe on the frozen body.';return;}doc.frames[index][foot]={x,y,landmark};error='';}}
  async function imported(event:Event){try{const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;if(file.size>2_000_000)throw new Error('Sole measurements exceed 2 MB.');doc=validated(JSON.parse(await file.text()));status='Loaded measurements for these exact frozen frames.';error='';}catch(e){error=(e as Error).message;}}
  function save(){try{validated(JSON.parse(JSON.stringify(doc)));localStorage.setItem(storage,JSON.stringify(doc));status='Rendered sole measurements saved locally.';error='';}catch(e){error=(e as Error).message;}}
  function exported(){try{validated(JSON.parse(JSON.stringify(doc)));const url=URL.createObjectURL(new Blob([JSON.stringify({...doc,measurements:measured,qualified:false})],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`soles-${fixed.jobId}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){error=(e as Error).message;}}
  onMount(()=>{try{const text=localStorage.getItem(storage);if(text)doc=validated(JSON.parse(text));}catch(e){error=(e as Error).message;}});
</script>
<section class="sole bu-stack" aria-label="Rendered sole qualification"><h4>Rendered sole qualification</h4><p>Pick a visible heel or toe on each full-support frame. Use the same anatomical landmark throughout a stance. Leave hidden or ambiguous feet unmarked. Each root sample equals authored velocity × source time. The result measures frame-boundary displacement, not continuous playback or an engine speed after retiming. It does not move the body or certify natural motion.</p>
  <label>Import sole measurements<input type="file" accept="application/json" onchange={imported}></label>
  <div class="bu-actions"><label>Measured foot<select class="bu-select" bind:value={foot}><option value="RIGHT LEG">Anatomical right</option><option value="LEFT LEG">Anatomical left</option></select></label><label>Visible landmark<select class="bu-select" bind:value={landmark}><option value="heel">Heel</option><option value="toe">Toe</option></select></label><button class="bu-btn" onclick={()=>delete doc.frames[index][foot]}>Clear selected sole mark</button></div>
  <canvas bind:this={canvas} aria-label="Mark visible sole landmark" onpointerdown={mark}></canvas><p>Raw frame {index+1}: right {doc.frames[index]['RIGHT LEG']?JSON.stringify(doc.frames[index]['RIGHT LEG']):'unmarked'}; left {doc.frames[index]['LEFT LEG']?JSON.stringify(doc.frames[index]['LEFT LEG']):'unmarked'}.</p>
  {#each measured as m}<p>Stance {m.window+1}, {m.foot}: {m.marked}/{m.expected} full-support marks across {Math.round(m.temporalSpan*1000)} of {Math.round(m.supportDuration*1000)} ms. {m.complete?`Sampled world displacement span ${m.worldSpan!.toFixed(2)} px.`:m.consistent?'Incomplete; no displacement result.':'Mixed heel/toe landmarks; no displacement result.'} Frames {m.samples.map(s=>s.index+1).join(', ')}.</p>{/each}
  <label>Sole review notes<textarea class="bu-input" bind:value={doc.notes}></textarea></label><div class="bu-actions"><button class="bu-btn" onclick={save}>Save sole measurements</button><button class="bu-btn" onclick={exported}>Export sole measurements</button></div><p role="status">{status}</p>{#if error}<p role="alert" class="bu-error">{error}</p>{/if}
</section>
<style>.sole{padding:16px}.sole canvas{width:320px;max-width:100%;height:auto;image-rendering:pixelated;touch-action:none}.sole textarea{min-height:80px}</style>
